import{_ as t,o as e,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Containerized deployment of Ceph with KCLI","description":"","frontmatter":{"title":"Containerized deployment of Ceph with KCLI","date":"2026-05-12T00:00:00.000Z","updated":"2026-05-12T00:00:00.000Z","tags":["Ceph","containerization","KCLI","Crimson OSD","orchestration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Containerized_deployment_of_Ceph_with_KCLI.md","filePath":"posts/2026/Containerized_deployment_of_Ceph_with_KCLI.md","lastUpdated":1780459816000}'),a={name:"posts/2026/Containerized_deployment_of_Ceph_with_KCLI.md"};function r(d,o,s,n,c,p){return e(),i("div",null,[...o[0]||(o[0]=[l('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次分享由 Crimson 团队成员 Shraddha 主讲，介绍了如何使用 KCLI 工具在容器化环境中部署 Ceph 集群。内容涵盖了 KCLI 的基本概念、配置方式、Classic OSD 与 Crimson OSD 的部署流程，以及实际演示中遇到的常见问题与解决方案。</p><h2 id="为什么需要容器化部署" tabindex="-1">为什么需要容器化部署 <a class="header-anchor" href="#为什么需要容器化部署" aria-label="Permalink to &quot;为什么需要容器化部署&quot;">​</a></h2><p>在使用 KCLI 之前，Shraddha 的开发方式是在本地开发机上进行裸机（bare metal）安装。这种方式存在以下几个明显局限：</p><ul><li><strong>OS 版本锁定</strong>：只能使用开发机上已安装的特定 OS 版本，难以复现在其他环境下出现的问题。</li><li><strong>镜像 tag 难以对齐</strong>：当用户使用特定 tag 时，裸机环境下很难精确匹配，排查问题效率低。</li><li><strong>cephadm 与 dashboard 部署困难</strong>：涉及 cephadm 或 dashboard 的开发调试在裸机环境下操作繁琐。</li><li><strong>Rocky 10 推广受阻</strong>：团队正在推进 Rocky 10 在Ceph 中的全面支持，容器化部署可以大幅加速这一进程。</li></ul><p>使用 KCLI 的容器化部署方案可以消除上述约束，让开发者专注于实际问题本身，而不是环境差异带来的干扰。</p><h2 id="kcli-简介" tabindex="-1">KCLI 简介 <a class="header-anchor" href="#kcli-简介" aria-label="Permalink to &quot;KCLI 简介&quot;">​</a></h2><p>KCLI 是一个为不同虚拟化提供商提供统一用户体验的工具。它可以：</p><ul><li>按需 provision 虚拟机（VM），自由指定 OS 镜像、内存、CPU 数量</li><li>配置磁盘类型（NVMe、SSD、HDD）和磁盘大小</li><li>自动安装指定软件包</li><li>将本地源码目录挂载到 VM，实现代码修改实时生效，无需重复构建和部署</li></ul><h2 id="kcli-配置文件结构" tabindex="-1">KCLI 配置文件结构 <a class="header-anchor" href="#kcli-配置文件结构" aria-label="Permalink to &quot;KCLI 配置文件结构&quot;">​</a></h2><p>KCLI 的核心是一个 YAML 格式的配置文件（<code>ceph-cluster.yaml</code>），主要包含以下部分：</p><ul><li><strong>parameters段</strong>：定义节点数量、IP offset、磁盘大小、CPU 数量、使用的 OS 镜像等全局参数。</li><li><strong>节点定义段</strong>：为每个节点单独配置镜像、SSH 密钥、网络、存储池（pool）等。</li><li><strong>源码挂载</strong>：可将本地 Ceph 源码目录挂载到 VM，修改立即同步到运行中的集群。</li><li><strong>文件与脚本复制</strong>：支持将特定脚本或配置文件复制到 VM 节点。</li><li><strong>bootstrap 脚本</strong>：定义 Ceph 特定的初始化逻辑，包括 Classic 和 Crimson 两种模式。</li></ul><h2 id="classic-osd-部署流程" tabindex="-1">Classic OSD 部署流程 <a class="header-anchor" href="#classic-osd-部署流程" aria-label="Permalink to &quot;Classic OSD 部署流程&quot;">​</a></h2><p>Classic 模式的 bootstrap 脚本流程相对简单：</p><ol><li>指定 Ceph 镜像（可以是 release 镜像、CI 构建的开发镜像或自定义镜像）</li><li>下载并赋予 cephadm 二进制可执行权限</li><li>执行 <code>cephadm bootstrap</code> 命令，可配置 dashboard 初始密码、是否跳过 monitoring 等选项</li><li>从配置中获取 FSID</li><li>为每个节点复制 SSH 密钥并加入集群</li><li>通过 <code>ceph orch apply OSD</code> 命令批量部署 OSD</li></ol><h2 id="crimson-osd-部署流程" tabindex="-1">Crimson OSD 部署流程 <a class="header-anchor" href="#crimson-osd-部署流程" aria-label="Permalink to &quot;Crimson OSD 部署流程&quot;">​</a></h2><p>Crimson 模式在 Classic 基础上增加了若干配置步骤：</p><ol><li>同样定义镜像、部署 cephadm、执行 bootstrap</li><li>启用 Crimson feature flag</li><li>设置默认 pool 类型为 Crimson</li><li>配置 <code>crimson_cpu_num</code> 等 Crimson 专属参数</li><li>添加调试相关配置（便于开发调试）</li><li>部署 Crimson OSD：在 <code>ceph orch apply OSD</code> 命令中添加 <code>--osd-type crimson</code> 参数，或使用 <code>ceph orch add OSD</code> 单独添加指定 OSD</li></ol><h2 id="实际演示要点" tabindex="-1">实际演示要点 <a class="header-anchor" href="#实际演示要点" aria-label="Permalink to &quot;实际演示要点&quot;">​</a></h2><p>演示分为 Classic 和 Crimson 两个集群的完整部署过程，关键步骤如下：</p><p><strong>环境准备：</strong></p><ul><li>更新包管理器</li><li>安装 libvirt（虚拟化引擎）</li><li>将当前用户加入 libvirt 组</li><li>配置 SSH，开启 <code>PermitRootLogin yes</code> 并重启 SSH 服务</li><li>生成 SSH 密钥（若不存在）</li></ul><p><strong>KCLI 初始化：</strong></p><ul><li>安装 KCLI（官方提供一键安装脚本）</li><li>创建默认 pool 和默认网络</li><li>下载所需 OS 镜像（演示使用 Fedora 43；也支持自定义镜像，通过 <code>-H</code> 参数指定 URL）</li></ul><p><strong>集群部署：</strong></p><ul><li>使用 <code>kcli create plan</code> 命令基于 YAML 配置文件创建集群</li><li>VM 启动后自动执行 bootstrap 脚本</li><li>通过 <code>cloud-init</code> 输出日志（<code>/var/log/cloud-init-output.log</code>）跟踪部署进度</li><li>使用 <code>podman ps</code> 查看容器启动状态</li><li>使用 <code>cephadm shell</code> 进入 Ceph 管理环境执行 <code>ceph health</code>、<code>ceph pg dump</code> 等命令验证集群状态</li></ul><p><strong>Crimson 集群特别注意事项：</strong></p><ul><li>部署新集群前必须删除旧的 plan 并重建网络，否则会出现难以排查的网络错误</li><li>多人共用同一台机器时，每人应使用不同的 network 和 pool</li><li>若使用 OSD spec 文件，需确保该文件已在 <code>ceph-cluster.yaml</code> 中配置为复制到 VM</li><li>镜像 tag 必须明确指定，否则无法拉取镜像</li></ul><p><strong>验证 Crimson OSD：</strong></p><ul><li>查看 OSD 日志，确认 Crimson 进程已启动，即可确认为 Crimson OSD</li></ul><h2 id="常见问题与解决方案" tabindex="-1">常见问题与解决方案 <a class="header-anchor" href="#常见问题与解决方案" aria-label="Permalink to &quot;常见问题与解决方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td>找不到 OSD spec 文件</td><td>YAML 中引用了未复制的文件</td><td>在 <code>ceph-cluster.yaml</code> 中添加文件复制配置</td></tr><tr><td>无法拉取镜像</td><td>未指定镜像 tag</td><td>在配置中明确指定完整 tag</td></tr><tr><td>MON 无法获取 IP</td><td>缺少网络工具包</td><td>在 bootstrap 脚本中预装所需网络工具</td></tr><tr><td>SSH 连接失败</td><td>未开启 root 登录或密钥缺失</td><td>配置 <code>PermitRootLogin yes</code>，确保密钥存在</td></tr><tr><td>磁盘空间不足</td><td>配置的磁盘大小过小</td><td>调整 YAML 中的磁盘大小参数</td></tr></tbody></table><h2 id="q-a-摘要" tabindex="-1">Q&amp;A 摘要 <a class="header-anchor" href="#q-a-摘要" aria-label="Permalink to &quot;Q&amp;A 摘要&quot;">​</a></h2><p><strong>KCLI 的系统要求？</strong> KCLI 本身安装要求不高，但 VM 的资源需求取决于配置文件中的定义。已验证可用的系统包括 Ubuntu、Fedora 和 RHEL。</p><p><strong>旧镜像的磁盘空间清理？</strong> 需要手动清理，KCLI 不会自动回收未使用镜像占用的空间。</p><p><strong>能否对 KCLI 集群执行升级？</strong> 可以，使用 cephadm 在 KCLI 集群上执行升级完全可行。</p><p><strong>集群使用完毕后如何销毁？</strong> 建议及时销毁，避免占用系统资源（尤其是日志会持续增长）。销毁命令为 <code>kcli delete plan &lt;plan-name&gt;</code>，操作非常简单。</p><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li>Classic 部署配置：GitHub 仓库（以该仓库为配置的 source of truth）</li><li>Crimson 部署配置：Ceph Wiki 页面（包含 Crimson 专属配置说明）</li><li>问题反馈：可通过 Slack 或邮件列表联系 Shraddha，团队也在考虑为 KCLI 相关讨论创建专属 Slack 频道</li></ul>',39)])])}const m=t(a,[["render",r]]);export{C as __pageData,m as default};
